export function usageTierByIndex(answers: string[]): Record<UsageTier, number[]> {
  const out: Record<UsageTier, number[]> = { common: [], familiar: [], rare: [] };
  answers.forEach((w, i) => {
    const tier = WORD_TIERS[w] ?? "familiar";
    out[tier].push(i);
  });
  return out;
}
